@-moz-document domain("discord.com") {
/* Set the background image on html and body */
    html, body {
        background-image: url("https://i.imgur.com/zpftvsX.jpeg") !important;
        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        height: 100% !important;
        width: 100% !important;
        background-attachment: fixed !important;
    }

    /* Make main app container background transparent */
    .appMount-2yBXZl {
        background: transparent !important;
    }

    /* Remove background colors on major containers to reveal your image */
    .theme-dark, 
    .layerContainer-2e7VN-, 
    .layer-3N0YU2, 
    .content-3dzVd8 {
        background: transparent !important;
    }

    /* Panels keep blur with transparency so background shows */
    .chatContent-3KubbW, 
    .sidebar-1tnWFu, 
    .container-1NXEtd {
        background-color: rgba(0, 0, 0, 0.5) !important;  /* semi-transparent dark */
        backdrop-filter: blur(10px) !important;
        -webkit-backdrop-filter: blur(10px) !important;
        border-radius: 10px !important;
    }
}
